import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.DfDAiEgj.js";const r="/2bPM/img/ML_structure.png",o="/2bPM/img/ML_Lifecycle.png",s="/2bPM/img/find_hyperparameter.png",n="/2bPM/img/train_tech.png",_=JSON.parse('{"title":"模型过程","description":"","frontmatter":{},"headers":[],"relativePath":"project/Model Process.md","filePath":"project/Model Process.md","lastUpdated":null}'),c={name:"project/Model Process.md"};function p(d,a,h,u,m,f){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="模型过程" tabindex="-1">模型过程 <a class="header-anchor" href="#模型过程" aria-label="Permalink to &quot;模型过程&quot;">​</a></h1><h2 id="整体框架" tabindex="-1">整体框架 <a class="header-anchor" href="#整体框架" aria-label="Permalink to &quot;整体框架&quot;">​</a></h2><p><img src="'+r+'" alt="整体框架"></p><h2 id="生命周期-1" tabindex="-1">生命周期 <a href="https://ucbrise.github.io/cs294-ai-sys-fa19/assets/lectures/lec03/03_ml-lifecycle.pdf" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#生命周期-1" aria-label="Permalink to &quot;生命周期 [1]&quot;">​</a></h2><p><img src="'+o+'" alt="模型的生命周期"></p><h2 id="模型开发" tabindex="-1">模型开发 <a class="header-anchor" href="#模型开发" aria-label="Permalink to &quot;模型开发&quot;">​</a></h2><p>数据采集-》数据清理&amp;可视化</p><p>需要数据工程师来帮助：</p><ul><li>识别数据的潜在来源</li><li>从多个来源连接数据</li><li>定位缺失值和异常值</li><li>绘制趋势以识别异常</li></ul><p>—》特征工程&amp;模型设计-》训练&amp;评估</p><p>数据科学家为此而生：</p><ul><li>构建信息丰富的特性</li><li>功能设计新的模型架构</li><li>重新调整超参数</li><li>验证预测准确性</li></ul><h3 id="特征和特征工程" tabindex="-1">特征和特征工程 <a class="header-anchor" href="#特征和特征工程" aria-label="Permalink to &quot;特征和特征工程&quot;">​</a></h3><p>特征:输入的属性或特征</p><p>为什么从模型开发中直接生成训练有素的模型是一个坏主意</p><p>为了解决新问题，正在构建模型</p><ul><li>需要跟踪组合和验证端到端的准确性。</li><li>需要对模型进行单元和集成测试</li></ul><p>TODO:</p><p>Dynamic Features: features can often be modified faster than models：</p><ul><li>Useful for addressing fast changing dynamics (e.g., user preferences can be encoded in click history features).</li><li>Issue:resulting potential covariate shift can be problematic</li></ul><h3 id="超参数" tabindex="-1">超参数 <a class="header-anchor" href="#超参数" aria-label="Permalink to &quot;超参数&quot;">​</a></h3><p>参数和更普遍的配置细节不是通过培训直接确定的</p><ul><li>手动设置或使用交叉验证进行调整</li><li>为什么不直接学习?</li></ul><p><img src="'+s+'" alt="寻找超参"></p><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3><p>Training Pipelines -&gt; Code Trained Models -&gt; Binaries</p><h3 id="训练科技" tabindex="-1">训练科技 <a class="header-anchor" href="#训练科技" aria-label="Permalink to &quot;训练科技&quot;">​</a></h3><p><img src="'+n+'" alt="训练科技"></p><h2 id="推断" tabindex="-1">推断 <a class="header-anchor" href="#推断" aria-label="Permalink to &quot;推断&quot;">​</a></h2><p>目的:在深度神经复杂的突发运行下在~10ms内进行预测</p><h3 id="并包括反馈" tabindex="-1">并包括反馈 <a class="header-anchor" href="#并包括反馈" aria-label="Permalink to &quot;并包括反馈&quot;">​</a></h3><ol><li>模型更新:当新数据来重新培训。</li></ol><ul><li><strong>周期性</strong>:权衡利用批处理和验证。因为模型可能会过期一段时间。</li><li><strong>持续地(在线学习)</strong>:最新鲜的模型。需要验证，学习率?…非常复杂。</li></ul><ol start="2"><li>特征更新:新数据可能会改变特征</li></ol><ul><li>例如:更新用户的点击历史-》新预测</li><li>比在线学习更健壮</li></ul><p>新的训练数据到达并改变损失面。而不是从以前的解的随机权重开始重新开始</p><h3 id="反馈圈" tabindex="-1">反馈圈 <a class="header-anchor" href="#反馈圈" aria-label="Permalink to &quot;反馈圈&quot;">​</a></h3><p>Models can bias the data they collect</p><ul><li>Example: content recommendation</li><li>Future models may reflect earlier model bias</li></ul><p>Exploration –Exploitation Trade-off</p><ul><li>Exploration:observe diverse outcomes</li><li>Exploitation:leverage model to takepredicted best action</li></ul><p>Solutions：</p><ul><li>Randomization (ε-greedy): occasionally ignore the model</li><li>Bandit Algorithms/Thompson Sampling: optimally balance exploration and exploitation àactive area of research</li></ul>',43)])])}const g=e(c,[["render",p]]);export{_ as __pageData,g as default};
